namespace ghidra.file.formats.android.wdex;

using ghidra.program.model.listing;

/**
 * Android .WDEX files.
 * 
 * https://android.googlesource.com/platform/art/+/master/runtime/vdex_file.h
 */
public sealed class WdexConstants {

	/**
	  * <pre>
	  * static constexpr uint8_t kVdexInvalidMagic[] = { 'w', 'd', 'e', 'x' };
	  * </pre>
	 */
	public static string MAGIC = "wdex";

	public static string kVdexInvalidMagic = MAGIC;

	/**
	 * Returns true if the given program contain WDEX information.
	 */
	public static bool isWDEX(Program program) {
		if (program != null) {
			try {
				byte[] bytes = new byte[MAGIC.length()];
				program.getMemory().getBytes(program.getMinAddress(), bytes);
				return MAGIC.equals(new string(bytes));
			}
			catch (Exception e) {
				//ignore
			}
		}
		return false;
	}
}
